import itertools


def _route(data, coupon_rule, minimum_duration):
    required = data.get("required", [])
    bit_for = {node: 1 << i for i, node in enumerate(required)}
    full = (1 << len(required)) - 1
    source = data["source"]
    initial_mask = bit_for.get(source, 0)
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)

    budget = data["coupons"]
    start = data["start"]
    initial = (source, initial_mask, 0)
    best = {initial: start}
    queue = [(start, source, initial_mask, 0)]

    while queue:
        arrival, node, mask, used = heapq.heappop(queue)
        state = (node, mask, used)
        if best.get(state) != arrival:
            continue
        if (node == data["target"] and mask == full and
                (coupon_rule == "at_most" or used == budget)):
            return {"arrival": arrival}

        for edge in graph[node]:
            depart = max(arrival, edge["open"])
            if depart >= edge["close"]:
                continue
            duration = edge["duration"]
            outcomes = [(duration, used)]
            if used < budget:
                discounted = max(minimum_duration,
                                 duration - edge.get("discount", 0))
                outcomes.append((discounted, used + 1))
            for travel, next_used in outcomes:
                next_time = depart + travel
                if next_time > data["deadline"]:
                    continue
                next_node = edge["v"]
                next_mask = mask | bit_for.get(next_node, 0)
                next_state = (next_node, next_mask, next_used)
                if next_time < best.get(next_state, float("inf")):
                    best[next_state] = next_time
                    heapq.heappush(queue,
                                   (next_time, next_node, next_mask, next_used))
    return {"arrival": None}


def _ledger(data):
    cutoff = data.get("cutoff", 10**9)
    chosen = {}
    for position, event in enumerate(data["events"]):
        sequence = event.get("sequence", 0)
        if sequence > cutoff:
            continue
        event_id = event.get("id", "anonymous:" + str(position))
        key = (sequence, event.get("revision", 0), position)
        if event_id not in chosen or key > chosen[event_id][0]:
            chosen[event_id] = (key, event)

    balances = dict(data.get("opening", {}))
    mode = data["rounding"]

    def rounded(numerator):
        if mode == "half_up":
            return (numerator + 5000) // 10000
        return numerator // 10000

    for _, event in chosen.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = rounded(raw * (10000 - discount))
        tax = rounded(raw * event.get("tax_bp", 0))
        total = net + tax
        if event.get("kind") == "refund":
            total = -total
        key = (event.get("account", "default") + "|" +
               event.get("currency", "USD"))
        balances[key] = balances.get(key, 0) + total
    return {"balances": balances}


def _resolver(data):
    packages = data["packages"]
    names = sorted(packages, reverse=True)
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    roots = data["roots"]
    rows_by_name = {
        name: {row["version"]: row for row in rows}
        for name, rows in packages.items()
    }

    domains = {}
    for name in names:
        versions = [v for v in rows_by_name[name]
                    if v not in blocked.get(name, []) and
                    (name not in pins or v == pins[name])]
        domains[name] = sorted(versions, reverse=True) + [-1]

    def active_dependencies(row):
        result = []
        for dep in row.get("deps", []):
            feature = dep.get("feature", "")
            if not feature or feature in features:
                result.append(dep)
        return result

    def valid(selection):
        installed = {name for name, version in selection.items() if version != -1}
        graph = {name: [] for name in installed}
        for name, bounds in roots.items():
            version = selection[name]
            if version == -1 or not bounds[0] <= version <= bounds[1]:
                return False

        closure = set()
        pending = list(roots)
        while pending:
            name = pending.pop()
            if name in closure:
                continue
            version = selection[name]
            if version == -1:
                return False
            closure.add(name)
            row = rows_by_name[name][version]
            for dep in active_dependencies(row):
                dep_name = dep["name"]
                dep_version = selection[dep_name]
                if (dep_version == -1 or
                        not dep["min"] <= dep_version <= dep["max"]):
                    return False
                graph[name].append(dep_name)
                pending.append(dep_name)
        if closure != installed:
            return False

        finished, active = set(), set()

        def visit(name):
            if name in active:
                return False
            if name in finished:
                return True
            active.add(name)
            for other in graph[name]:
                if not visit(other):
                    return False
            active.remove(name)
            finished.add(name)
            return True

        return all(visit(name) for name in graph)

    for values in itertools.product(*(domains[name] for name in names)):
        selection = dict(zip(names, values))
        if valid(selection):
            return {"versions": {name: version for name, version in selection.items()
                                  if version != -1}}
    return {"error": "unsatisfiable"}


def _intervals(data):
    jobs = data["jobs"]
    k = data["k"]
    blocked = set(data.get("blocked", []))
    mandatory = set(data.get("mandatory", []))
    quotas = data.get("quotas", {})
    best_value = None
    best_ids = None

    for chosen in itertools.combinations(jobs, k):
        ids = {job["id"] for job in chosen}
        if ids & blocked or not mandatory.issubset(ids):
            continue
        counts = {}
        for job in chosen:
            group = job["group"]
            counts[group] = counts.get(group, 0) + 1
        if any(not low <= counts.get(group, 0) <= high
               for group, (low, high) in quotas.items()):
            continue

        events = []
        for job in chosen:
            events.append((job["start"], 1))
            events.append((job["end"], -1))
        active = 0
        feasible = True
        for _, delta in sorted(events):
            active += delta
            if active > 2:
                feasible = False
                break
        if not feasible:
            continue

        selected_ids = sorted(ids)
        value = sum(job["value"] for job in chosen)
        if (best_value is None or value > best_value or
                (value == best_value and selected_ids < best_ids)):
            best_value, best_ids = value, selected_ids

    if best_value is None:
        return {"error": "impossible"}
    return {"selected": best_ids, "value": best_value}


